INSERT INTO areas(id,slug,name) VALUES(68,'elven-valley','The Elven Valley');
INSERT INTO rooms(id,slug,name,description,area_id,first_visited,visits,x,y,z,trap) VALUES(3316,'path-in-the-elven-valley','path in the Elven Valley','You''re standing on a path that is known to lead to the Elven city Mytthos, oddly named by humans instead of the Elves themselves.  The path is bordered neatly on both sides by logs, which can be easily passed on foot in many places.  Exits are southwest toward the mountain road, and north along the path.',68,'2026-09-28T19:11:09',1,29,24,0,NULL);
INSERT INTO rooms(id,slug,name,description,area_id,first_visited,visits,x,y,z,trap) VALUES(3317,'path-in-the-elven-valley-1','path in the Elven Valley','You''re standing on a path that is known to lead to the Elven city Mytthos, oddly named by humans instead of the Elves themselves.  The path is bordered neatly on both sides by logs, which can be easily passed on foot in many places.  Exits are to the north and south.',68,'2026-09-28T19:11:11',2,29,25,0,NULL);
