INSERT INTO rooms(id,slug,name,description,area_id,first_visited,visits,x,y,z,trap) VALUES(3349,'path-in-the-elven-valley-7','path in the Elven Valley','You''re standing on a path that is known to lead to the Elven city Mytthos, oddly named by humans instead of the Elves themselves.  There is a huge mithril door to the north, apparently the entrance to Mytthos.  Two paths run east and west of here, alongside the city wall.  This path continues southward.',68,'2026-10-02T21:47:52',5,25,31,0,NULL);
INSERT INTO rooms(id,slug,name,description,area_id,first_visited,visits,x,y,z,trap) VALUES(3350,'path-in-the-elven-valley-8','path in the Elven Valley','You''re on a path in the Elven Valley that leads around the city of Mytthos.  There are no fresh footprints on the path, even though you have seen elves creeping around.  The elves are not foolish enough to leave their trail to anyone who would like to follow them.  The further you stray from the gate to the city, the more you fear for your life. Exits are east and west.',68,'2026-10-02T21:48:00',5,26,31,0,NULL);
